cat > /tmp/sears-gen-base.cjs <<'EOF'
const fs = require("fs");
const p = JSON.parse(fs.readFileSync("palette.json", "utf8"));
const lines = [];
const seen = new Set();
const emit = (role, id) => {
  if (seen.has(id)) return;
  seen.add(id);
  const name = id.toUpperCase();
  lines.push(`// ${role}: the ${id.replace(/_/g, " ")} block`);
  lines.push(`export const ${name} = "${id}";`);
};
for (const [role, ids] of Object.entries(p.roles)) for (const id of ids) emit(role, id);
for (const id of p.objects) emit("object", id);
fs.writeFileSync("/tmp/sears-palette-consts.mjs", lines.join("\n") + "\n");
console.log(seen.size, "palette constants");
EOF
node /tmp/sears-gen-base.cjs && head -4 /tmp/sears-palette-consts.mjs

